const W=3600,H=2400,C={bg:'#080812',road:'#202033',neon:'#00ffaa',pink:'#ff33aa',yellow:'#ffdd00',danger:'#ff4433'};
export function createGameState(){return{titleScreen:{active:true},gameOver:{active:false},player:{x:W/2,y:H/2,angle:0,health:100,armor:25,money:500,inCar:false,car:null,ammo:42,shootCooldown:0},camera:{x:W/2,y:H/2},wanted:0,wantedTimer:0,mission:{step:0,complete:false},roads:roads(),buildings:buildings(),cars:cars(),npcs:npcs(),bullets:[],time:0};}
function roads(){return[{x:0,y:100,w:W,h:180},{x:0,y:820,w:W,h:180},{x:0,y:1540,w:W,h:180},{x:0,y:2260,w:W,h:140},{x:100,y:0,w:180,h:H},{x:900,y:0,w:180,h:H},{x:1700,y:0,w:180,h:H},{x:2500,y:0,w:180,h:H},{x:3300,y:0,w:180,h:H}];}
function buildings(){const a=[];for(let x=320;x<3300;x+=400)for(let y=330;y<2200;y+=360)a.push({x,y,w:280,h:250,c:['#17172b','#1d1830','#14242c'][a.length%3]});return a;}
function cars(){return Array.from({length:22},(_,i)=>({x:120+(i%6)*620,y:190+(i%4)*560,w:54,h:96,a:i%2?Math.PI/2:0,v:55+(i%5)*16,c:['#cc3355','#2277aa','#ddaa22','#55aa88','#aa44cc'][i%5],ai:true}));}
function npcs(){return Array.from({length:45},(_,i)=>({x:340+(i*173)%3000,y:350+(i*313)%1800,c:['#ffccaa','#cc8866','#8866cc','#55aa88'][i%4],alive:true}));}
export function updateGameState(s,dt=.016,k={},m={}){if(s.titleScreen.active||s.gameOver.active)return;const p=s.player;let x=0,y=0;if(k.w||k.W||k.ArrowUp)y--;if(k.s||k.S||k.ArrowDown)y++;if(k.a||k.A||k.ArrowLeft)x--;if(k.d||k.D||k.ArrowRight)x++;if(x||y){const l=Math.hypot(x,y);p.x+=x/l*190*dt;p.y+=y/l*190*dt;p.angle=Math.atan2(y,x);}p.x=Math.max(30,Math.min(W-30,p.x));p.y=Math.max(30,Math.min(H-30,p.y));s.time+=dt;s.camera.x+=(p.x-s.camera.x)*dt*6;s.camera.y+=(p.y-s.camera.y)*dt*6;for(const c of s.cars)if(c.ai){if(c.a===0)c.x+=c.v*dt;else c.y+=c.v*dt;if(c.x>W+100)c.x=-100;if(c.y>H+100)c.y=-100;}for(const n of s.npcs)if(n.alive){n.x+=Math.sin(s.time+n.x)*5*dt;n.y+=Math.cos(s.time+n.y)*5*dt;}if(s.mission.step===0&&p.x>W/2+300){s.mission.step=1;message('Reach Neon Market');}if(s.mission.step===1&&p.y<700){s.mission.step=2;s.mission.complete=true;p.money+=250;message('Mission complete +$250');}hud(s);}
function message(t){const e=document.getElementById('notification');if(e){e.textContent=t;e.classList.add('active');setTimeout(()=>e.classList.remove('active'),2200);}}
function hud(s){const p=s.player;for(const [id,v] of [['hp-value',`${Math.ceil(p.health)}/100`],['armor-value',`${p.armor}/100`],['money-value',`$${p.money}`],['ammo-count',p.ammo]]){const e=document.getElementById(id);if(e)e.textContent=v;}const e=document.getElementById('mission-panel');if(e)e.classList.toggle('active',!s.mission.complete);}
export function drawGame(c,s){const w=innerWidth,h=innerHeight;c.fillStyle=C.bg;c.fillRect(0,0,w,h);if(s.titleScreen.active)return;c.save();c.translate(w/2-s.camera.x,h/2-s.camera.y);c.fillStyle='#0d0d1c';c.fillRect(0,0,W,H);for(const r of s.roads){c.fillStyle=C.road;c.fillRect(r.x,r.y,r.w,r.h);}for(const b of s.buildings){c.fillStyle=b.c;c.fillRect(b.x,b.y,b.w,b.h);c.strokeStyle='#4f3f67';c.strokeRect(b.x,b.y,b.w,b.h);for(let x=b.x+25;x<b.x+b.w-10;x+=48){c.fillStyle='#00ffaa44';c.fillRect(x,b.y+28,20,28);c.fillRect(x,b.y+85,20,28);}}for(const v of s.cars){c.save();c.translate(v.x,v.y);c.rotate(v.a);c.fillStyle=v.c;c.fillRect(-v.w/2,-v.h/2,v.w,v.h);c.fillStyle='#112233';c.fillRect(-v.w/2+8,-v.h/2+16,v.w-16,22);c.restore();}for(const n of s.npcs)if(n.alive){c.fillStyle=n.c;c.beginPath();c.arc(n.x,n.y,12,0,7);c.fill();}c.save();c.translate(s.player.x,s.player.y);c.rotate(s.player.angle);c.fillStyle=C.neon;c.shadowBlur=18;c.shadowColor=C.neon;c.beginPath();c.arc(0,0,16,0,7);c.fill();c.restore();if(!s.mission.complete){c.strokeStyle=C.yellow;c.lineWidth=4;c.beginPath();c.arc(W/2+500,520,36+Math.sin(s.time*4)*8,0,7);c.stroke();}c.restore();}
export function saveGameState(s,slot=0){localStorage.setItem(`neon-${slot}`,JSON.stringify(s));}export function loadGameState(slot=0){try{return JSON.parse(localStorage.getItem(`neon-${slot}`));}catch{return null;}}
